describe('File Upload - Folder Organization', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
    cy.get('[data-testid="upload-area"]').should('be.visible');
  });

  it('should organize uploaded files into folders by file type', () => {
    const fileName = 'test-document.pdf';
    const fileType = 'application/pdf';

    cy.get('[data-testid="file-input"]').selectFile({
      contents: Cypress.Buffer.from('PDF content'),
      fileName: fileName,
      mimeType: fileType,
    });

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="folder-structure"]').should('be.visible');
    cy.get('[data-testid="folder-pdf"]').should('exist');
    cy.get('[data-testid="file-item"]').should('contain', fileName);
    cy.get('[data-testid="file-location"]').should('contain', 'PDF');
  });

  it('should organize multiple files into different folders based on type', () => {
    const files = [
      { name: 'document.pdf', type: 'application/pdf', folder: 'PDF' },
      { name: 'image.jpg', type: 'image/jpeg', folder: 'Images' },
      { name: 'spreadsheet.xlsx', type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', folder: 'Documents' },
    ];

    files.forEach((file) => {
      cy.get('[data-testid="file-input"]').selectFile({
        contents: Cypress.Buffer.from('file content'),
        fileName: file.name,
        mimeType: file.type,
      });

      cy.get('[data-testid="upload-button"]').click();
      cy.get('[data-testid="upload-success"]').should('be.visible');
    });

    cy.get('[data-testid="folder-structure"]').should('be.visible');
    cy.get(`[data-testid="folder-${files[0].folder.toLowerCase()}"]`).should('exist');
    cy.get(`[data-testid="folder-${files[1].folder.toLowerCase()}"]`).should('exist');
    cy.get(`[data-testid="folder-${files[2].folder.toLowerCase()}"]`).should('exist');

    files.forEach((file) => {
      cy.get('[data-testid="file-list"]').should('contain', file.name);
    });
  });

  it('should handle edge case of unsupported file types in default folder', () => {
    const fileName = 'unknown-file.xyz';
    const fileType = 'application/octet-stream';

    cy.get('[data-testid="file-input"]').selectFile({
      contents: Cypress.Buffer.from('unknown content'),
      fileName: fileName,
      mimeType: fileType,
    });

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="folder-other"]').should('exist');
    cy.get('[data-testid="file-item"]').should('contain', fileName);
    cy.get('[data-testid="file-location"]').should('contain', 'Other');
  });

  it('should maintain folder structure when uploading files with same name in different folders', () => {
    const fileName = 'report.pdf';
    const imageFileName = 'report.jpg';

    cy.get('[data-testid="file-input"]').selectFile({
      contents: Cypress.Buffer.from('PDF content'),
      fileName: fileName,
      mimeType: 'application/pdf',
    });

    cy.get('[data-testid="upload-button"]').click();
    cy.get('[data-testid="upload-success"]').should('be.visible');

    cy.get('[data-testid="file-input"]').selectFile({
      contents: Cypress.Buffer.from('Image content'),
      fileName: imageFileName,
      mimeType: 'image/jpeg',
    });

    cy.get('[data-testid="upload-button"]').click();
    cy.get('[data-testid="upload-success"]').should('be.visible');

    cy.get('[data-testid="folder-pdf"]').within(() => {
      cy.get('[data-testid="file-item"]').should('contain', fileName);
    });

    cy.get('[data-testid="folder-images"]').within(() => {
      cy.get('[data-testid="file-item"]').should('contain', imageFileName);
    });
  });
});
